def transform(grid):
    """Bridge interrupted strokes while leaving crossings unfilled."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Complete vertical strokes. Do not add a vertical bridge when both
    # endpoints belong to horizontal strokes (such as a bar crossing a bar).
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] != background]
        for a, b in zip(marks, marks[1:]):
            horizontal_a = ((c > 0 and grid[a][c - 1] != background) or
                            (c + 1 < w and grid[a][c + 1] != background))
            horizontal_b = ((c > 0 and grid[b][c - 1] != background) or
                            (c + 1 < w and grid[b][c + 1] != background))
            if horizontal_a and horizontal_b:
                continue
            for r in range(a + 1, b):
                out[r][c] = 2

    # Complete horizontal strokes unless both endpoints already lie within
    # vertical through-strokes. These intersections remain distinct.
    def vertical_through(r, c):
        return (r > 0 and r + 1 < h and
                out[r - 1][c] != background and out[r + 1][c] != background)

    for r in range(h):
        marks = [c for c in range(w) if out[r][c] != background]
        for a, b in zip(marks, marks[1:]):
            if vertical_through(r, a) and vertical_through(r, b):
                continue
            for c in range(a + 1, b):
                if out[r][c] == background:
                    out[r][c] = 2
    return out


