    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def has_horizontal_neighbor(r, c):
        return ((c > 0 and grid[r][c - 1] != background) or
                (c + 1 < w and grid[r][c + 1] != background))

    def has_vertical_neighbor(r, c):
        return ((r > 0 and grid[r - 1][c] != background) or
                (r + 1 < h and grid[r + 1][c] != background))

    # Bridge between successive marks in columns, except if both endpoints
    # already form horizontal strokes.
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] != background]
        for a, b in zip(marks, marks[1:]):
            if has_horizontal_neighbor(a, c) and has_horizontal_neighbor(b, c):
                continue
            for r in range(a + 1, b):
                out[r][c] = 2

