    def horizontal_through(r, c):
        return any(grid[r][x] != bg for x in range(c)) and any(
            grid[r][x] != bg for x in range(c + 1, w)
        )

    # Fill vertical line gaps, except where both endpoints lie on horizontal
    # through-lines (that would create an unintended crossbar).
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] != bg]
        for a, b in zip(marks, marks[1:]):
            if horizontal_through(a, c) and horizontal_through(b, c):
                continue
            for r in range(a + 1, b):
                out[r][c] = 2

